// spec: specs/companion.md
// seed: tests/seed.parent-auto.spec.ts
// Ребёнок QA-R2-V — в слоте parent-auto (постоянно в режиме ребёнка, решение 08.11 #8ca267); parent.json не используется.
// Слот может быть ещё не в режиме ребёнка (первый прогон) или уже в нём — goChildHome справляется с обоими. В конце сессия слота сохраняется (saveSlot).

import { test, expect, Page } from '@playwright/test';
import { CHILD_SLOTS, goChildHome, saveSlot, slotState } from '../child-slot.helpers';

const KID = CHILD_SLOTS['QA-R2-V'];
const CHILD_ID = KID.childId;

test.use({ storageState: slotState(KID) });

// refresh-токен Supabase одноразовый — сохранить сессию слота обратно после каждого теста
test.afterEach(async ({ page }) => {
  await saveSlot(page.context(), KID);
});

async function visibleText(page: Page) {
  return page.locator('body').innerText();
}

function expectRabbitTexts(text: string) {
  expect(text).not.toMatch(/בנג[׳']?י/);
  expect(text).not.toContain('להארנבת');
}

test.describe('Тексты спутника на экранах ребёнка — десктоп (#b3210e)', () => {
  test('QA-R2-V (ארנבת): отправка письма — «לשלוח לארנבת?», «בעיבוד», отзыв «כתבת ושלחת לארנבת» @desktop @data #b3210e', async ({ page }) => {
    await page.setViewportSize({ width: 1440, height: 900 });

    // 1. Записывать rpc/child_profile
    const companions: unknown[] = [];
    page.on('response', async (resp) => {
      if (!resp.url().includes('rpc/child_profile')) return;
      try {
        const body = await resp.json();
        const row = Array.isArray(body) ? body[0] : body;
        companions.push(row?.companion);
      } catch {
        /* не JSON */
      }
    });

    // Задержать submit_writing_attempt на ~3 с, чтобы поймать экран «בעיбוד»
    await page.route('**/rpc/submit_writing_attempt*', async (route) => {
      await new Promise<void>((resolve) => setTimeout(resolve, 3000));
      await route.continue();
    });

    const suffix = Array.from({ length: 6 }, () => String.fromCharCode(97 + Math.floor(Math.random() * 26))).join('');
    const text = `QA-AUTO-${suffix} בדיקה`;

    // 2. Дом ребёнка QA-R2-V в слоте parent-auto: передача «QA-R2-V, בואו נתחיל!» (первый прогон) или закрыть гейт (слот уже в режиме ребёнка)
    await goChildHome(page, KID);
    await expect(page).toHaveURL(new RegExp(`/${CHILD_ID}/home`));

    await expect
      .poll(() => companions.at(-1), {
        message: 'Предусловие: rpc/child_profile должен вернуть companion === "rabbit" у QA-R2-V',
      })
      .toBe('rabbit');

    // «תרגול כתיבה» -> первое задание каталога (кнопка на доме ведёт в последнее задание, поэтому /writing/pick)
    await page.goto(`/${CHILD_ID}/writing/pick`);
    await page.getByRole('list', { name: 'משימות כתיבה' }).getByRole('button').first().click();
    await expect(page).toHaveURL(new RegExp(`/${CHILD_ID}/writing/[^/]+/write`));

    // 3. Ввести текст (режим «הקלדה») -> отправка
    const typingMode = page.getByRole('radio', { name: 'הקלדה' });
    if (await typingMode.isVisible()) {
      await typingMode.click();
    }
    await page.getByRole('textbox', { name: 'אזור ההקלדה' }).fill(text);
    // В интерфейсе кнопка называется «לסיים תרגול» (в описании — «לשלוח»)
    await page.getByRole('button', { name: 'לסיים תרגול' }).click();

    const dialog = page.getByRole('dialog', { name: 'לשלוח לארנבת?' });
    await expect(dialog).toBeVisible();
    await expect(dialog.getByText(/אחרי השליחה הארנבת תקרא/)).toBeVisible();
    expectRabbitTexts(await visibleText(page));

    // 4. Подтвердить -> «בעיבוד»
    await dialog.getByRole('button', { name: 'לשלוח' }).click();
    await expect(page.getByText('הארנבת קוראת את מה שכתבת')).toBeVisible();
    await expect(page.getByText(/הארנבת מנסה שוב לבד/)).toBeVisible();
    expectRabbitTexts(await visibleText(page));

    // 5. Отзыв
    await expect(page).toHaveURL(new RegExp(`/${CHILD_ID}/writing/[^/]+/feedback`), { timeout: 60_000 });
    await expect(page.getByText(/כתבת ושלחת לארנבת/)).toBeVisible({ timeout: 60_000 });
    expectRabbitTexts(await visibleText(page));

    test.info().annotations.push({
      type: 'cleanup',
      description: `Письмо ${text} у QA-R2-V (${CHILD_ID}), попытка: ${page.url()}`,
    });
  });
});
